$('#csvFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const isXlsx=file.name.toLowerCase().endsWith('.xlsx');if(!isXlsx){const reader=new FileReader();reader.onload=()=>{csvSourceText=reader.result;bulkMode='csv';try{csvRows=parseCSV(csvSourceText);csvParseError=''}catch(error){csvRows=[];csvParseError=error.message}$$('.bulk-tab').forEach(x=>x.classList.toggle('active',x.dataset.mode==='csv'));$('#pastePane').classList.add('hidden');$('#csvPane').classList.remove('hidden');$('.upload-box b').textContent=file.name;$('.upload-box small').textContent=csvParseError?'CSV could not be read':csvRows.length+' records loaded';updateRecords()};reader.readAsText(file);e.target.value='';return}bulkMode='csv';try{csvRows=await readCardBulkWorkbook(file);csvParseError='';csvSourceText=CARD_BULK_HEADERS.join(',')+'\n';$$('.bulk-tab').forEach(x=>x.classList.toggle('active',x.dataset.mode==='csv'));$('#pastePane').classList.add('hidden');$('#csvPane').classList.remove('hidden');$('.upload-box b').textContent=file.name;$('.upload-box small').textContent=`${csvRows.length} records loaded`;updateRecords()}catch(error){csvRows=[];csvParseError=error.message;csvSourceText='';$('.upload-box small').textContent=error.message;updateRecords()}e.target.value=''};
